import collections, math, struct, zlib, sys
f='/app/text.gcode'
obj='?';x=y=z=0.0;e=0.0
segs=collections.defaultdict(list)
for lineno,line in enumerate(open(f),1):
    line=line.split(';')[0].strip()
    if not line: continue
    if line.startswith('M486'):
        parts=line.split()
        if len(parts)>=2 and parts[1].startswith('S'): obj=parts[1][1:]
        continue
    parts=line.split(); cmd=parts[0]
    if cmd=='G92':
        for q in parts[1:]:
            if q.startswith('E'):
                try:e=float(q[1:])
                except:pass
        continue
    if cmd not in ('G0','G1'):continue
    vals={}
    for p in parts[1:]:
        if p and p[0] in 'XYZEF':
            try:vals[p[0]]=float(p[1:])
            except:pass
    nx=vals.get('X',x);ny=vals.get('Y',y);nz=vals.get('Z',z);ne=vals.get('E',e)
    de=ne-e
    if obj=='0' and de>0 and (abs(nx-x)>1e-9 or abs(ny-y)>1e-9):
        segs[round(z,3)].append((x,y,z,nx,ny,nz,de))
    x,y,z,e=nx,ny,nz,ne
# points
pts=[]
for ss in segs.values():
    for s in ss:
        pts.append((s[0],s[1],s[2]));pts.append((s[3],s[4],s[5]))
# mean
n=len(pts)
mx=sum(p[0] for p in pts)/n;my=sum(p[1] for p in pts)/n;mz=sum(p[2] for p in pts)/n
print('mean',mx,my,mz,'n',n)
# covariance
cov=[[0.0]*3 for _ in range(3)]
for p in pts:
    d=(p[0]-mx,p[1]-my,p[2]-mz)
    for i in range(3):
        for j in range(3): cov[i][j]+=d[i]*d[j]
for i in range(3):
    for j in range(3): cov[i][j]/=n
print('cov')
for r in cov: print(['%.2f'%v for v in r])
# power iteration eigenvectors
def matvec(M,v): return [sum(M[i][j]*v[j] for j in range(3)) for i in range(3)]
def norm(v):
    l=math.sqrt(sum(a*a for a in v)); return [a/l for a in v] if l else v
ev=[]
M=[row[:] for row in cov]
for k in range(3):
    v=[1,1,1]
    for _ in range(200):
        v=norm(matvec(M,v))
    lam=sum(v[i]*sum(M[i][j]*v[j] for j in range(3)) for i in range(3))
    ev.append((lam,v))
    for i in range(3):
        for j in range(3): M[i][j]-=lam*v[i]*v[j]
for lam,v in ev: print('lam',lam,'vec',v)
